export const components={
  cpu:[{name:'1-core processor',price:2,capacity:2},{name:'2-core processor',price:4,capacity:4},{name:'4-core processor',price:7,capacity:8}],
  memory:[{name:'4 GB memory',price:2,capacity:2},{name:'8 GB memory',price:4,capacity:4},{name:'16 GB memory',price:7,capacity:8}],
  storage:[{name:'Basic storage',price:2,capacity:2},{name:'Fast storage',price:4,capacity:4},{name:'Parallel storage',price:7,capacity:8}]
};
export const contracts=[
  {name:'Restart life support',budget:10,target:2,description:'Process two station jobs per second within a 10-credit budget.'},
  {name:'Restore the archives',budget:12,target:4,description:'Process four jobs per second. Upgrade each bottleneck without exceeding 12 credits.'},
  {name:'Launch the research lab',budget:21,target:8,description:'Process eight jobs per second within 21 credits. Keep all three stages balanced.'}
];
export function evaluateBuild(selection,contractIndex){
  if(!Number.isInteger(contractIndex)||!contracts[contractIndex])throw new Error('Choose a valid contract.');
  const entries=Object.entries(components).map(([key,choices])=>{if(!Number.isInteger(selection[key])||!choices[selection[key]])throw new Error('Choose a valid component.');return {key,...choices[selection[key]]};});
  const cost=entries.reduce((total,item)=>total+item.price,0),throughput=Math.min(...entries.map(item=>item.capacity)),contract=contracts[contractIndex];
  return {cost,throughput,bottlenecks:entries.filter(item=>item.capacity===throughput).map(item=>item.key),success:cost<=contract.budget&&throughput>=contract.target,overBudget:cost>contract.budget};
}
export function mountBuilder(container){
  let chosen={cpu:0,memory:0,storage:0},contractIndex=0,completed=[];try{const saved=JSON.parse(localStorage.getItem('signal-quest-builder-v1')||'null');if(saved){evaluateBuild(saved.chosen,saved.contractIndex);chosen=saved.chosen;contractIndex=saved.contractIndex;completed=Array.isArray(saved.completed)?saved.completed.filter(n=>Number.isInteger(n)&&contracts[n]):[];}}catch{}
  const persist=()=>{try{localStorage.setItem('signal-quest-builder-v1',JSON.stringify({chosen,contractIndex,completed}));}catch{}};
  function render(){const c=contracts[contractIndex],r=evaluateBuild(chosen,contractIndex);container.innerHTML=`<div class="mission-heading"><div><div class="eyebrow">STATION BUILDER · ${completed.length} / 3 CONTRACTS</div><h2>Build a better computer.</h2></div><span class="concept">Systems thinking</span></div><p class="intro">Fit out the station’s computing core. Upgrade its processor, memory, and storage, then see what limits the whole system.</p><div class="builder-contract"><div><div class="eyebrow">CONTRACT ${contractIndex+1}</div><h3>${c.name}</h3><p>${c.description}</p></div><label>Choose contract <select id="contract">${contracts.map((item,i)=>`<option value="${i}" ${i===contractIndex?'selected':''}>${i+1}. ${item.name}${completed.includes(i)?' ✓':''}</option>`).join('')}</select></label></div><div class="builder-floor">${Object.entries(components).map(([key,choices],index)=>`<section class="component-bay"><div class="eyebrow">STAGE 0${index+1} · ${key.toUpperCase()}</div><h3>${{cpu:'Run instructions',memory:'Hold active data',storage:'Read and write data'}[key]}</h3><div class="capacity-meter" aria-label="${choices[chosen[key]].capacity} jobs per second">${Array.from({length:8},(_,i)=>`<span class="${i<choices[chosen[key]].capacity?'filled':''}"></span>`).join('')}</div><strong class="component-capacity">${choices[chosen[key]].capacity} <span>jobs / second</span></strong><div class="component-options">${choices.map((option,i)=>`<button class="component-option ${chosen[key]===i?'chosen':''}" data-key="${key}" data-tier="${i}" aria-pressed="${chosen[key]===i}"><span>${option.name}</span><span>${option.price} cr</span></button>`).join('')}</div></section>`).join('')}</div><div class="builder-metrics"><div><span>Total cost</span><strong class="${r.overBudget?'over-budget':''}">${r.cost} <small>/ ${c.budget} cr</small></strong></div><div><span>System throughput</span><strong>${r.throughput} <small>jobs / sec</small></strong></div><div><span>Limiting stages</span><strong class="bottlenecks">${r.bottlenecks.map(x=>x.toUpperCase()).join(' + ')}</strong></div></div><div class="builder-test"><button id="benchmark" class="primary">▶ Run benchmark</button><p id="benchmark-result" role="status" aria-live="polite">Test your configuration against the contract.</p></div><div class="learning-row"><section class="field-notes"><div class="eyebrow">FIELD NOTES</div><h3>A system is only as fast as its bottleneck.</h3><p>In this simplified pipeline, each job uses all three stages. Total throughput is limited by the slowest stage. A faster CPU will not help while storage is the limit.</p></section><section class="help-panel"><div class="eyebrow">TRY AN EXPERIMENT</div><p>Upgrade only the CPU. What happens to total throughput? Now bring memory and storage up to the same capacity and compare.</p><p>This teaching model assumes independent, fully occupied stages and unlimited queues. Real computers also depend on the workload, contention, and many other factors.</p></section></div>`;
    container.querySelector('#contract').addEventListener('change',e=>{contractIndex=Number(e.target.value);persist();render();});
    container.querySelectorAll('[data-tier]').forEach(b=>b.addEventListener('click',()=>{chosen[b.dataset.key]=Number(b.dataset.tier);persist();render();}));
    container.querySelector('#benchmark').addEventListener('click',()=>{const result=evaluateBuild(chosen,contractIndex);if(result.success&&!completed.includes(contractIndex))completed.push(contractIndex);persist();render();const message=container.querySelector('#benchmark-result');message.textContent=result.success?`Contract complete. Your system delivers ${result.throughput} jobs per second for ${result.cost} credits.`:result.overBudget?`You are ${result.cost-c.budget} credits over budget. Choose a less expensive configuration.`:`Your system processes ${result.throughput} of the required ${c.target} jobs per second. Upgrade ${result.bottlenecks.join(' and ')}.`;message.className=result.success?'passed':'failed';});
  }
  render();return {getState:()=>({chosen:{...chosen},contractIndex,completed:[...completed],...evaluateBuild(chosen,contractIndex)})};
}
